  <?php if ($online): ?>
  <div class="field<?= $cls('facebook_response') ?>" data-show-checked="role_interests[]=Chat Agent|New Muslim Mentor"><span class="field-label">Do you currently have a Facebook account? <span class="req">*</span></span>
